settings.script:
# Changes the password of the connection account itself. passwd asks
# for the current password first, unless the account is root.
passwd
@case (?i)\b(current|old|existing)\b[^:\n]*password:
<OLDPASS>
@expect assword:
@case (?i)\bnew\b[^:\n]*password:
@end
<NEWPASS>
@expect assword:
<NEWPASS>
@regex (?i)(success|(?<!not |un)(updated|changed)\b|\bdone\b)

# Changes the password of the connection account itself, and that of its
# login keychain. An account that never logged in at the Mac has no login
# keychain (-25294), which is fine; any other keychain error is reported.
sysadminctl -newPassword - -oldPassword -
@expect Old password:
<OLDPASS>
@expect New password:
<NEWPASS>
@case Incorrect password
@fail The current password was refused.
@case keychain password \(-25294\)
@case keychain password \(
@fail The login keychain password was not changed.
@case - Done
@end

# Changes the password of the connection account itself.
@timeout 20
@expect >
net user <USER> *
@expect password
<NEWPASS>
@expect password
<NEWPASS>
@expect successfully
